package ama.api;
import ama.access.MeetingAccess;import ama.contract.IdentityContracts.*;import ama.db.TransactionRunner;import ama.recording.RecordingService;import jakarta.servlet.http.HttpServletRequest;import java.io.IOException;import java.util.*;import org.springframework.http.ResponseEntity;import org.springframework.web.bind.annotation.*;
/** The request selects no file, purpose, storage key or transcript text. */
@RestController class RecordingTranscriptController {
 private final RecordingTranscriptRuntime runtime;private final RecordingService recordings;private final MeetingAccess access;private final TransactionRunner tx;
 private final com.fasterxml.jackson.databind.ObjectMapper json=new com.fasterxml.jackson.databind.ObjectMapper(com.fasterxml.jackson.core.JsonFactory.builder().enable(com.fasterxml.jackson.core.StreamReadFeature.STRICT_DUPLICATE_DETECTION).streamReadConstraints(com.fasterxml.jackson.core.StreamReadConstraints.builder().maxNestingDepth(4).maxStringLength(256).maxNameLength(64).maxNumberLength(19).build()).build()).enable(com.fasterxml.jackson.databind.DeserializationFeature.FAIL_ON_TRAILING_TOKENS);
 RecordingTranscriptController(RecordingTranscriptRuntime runtime,RecordingService recordings,MeetingAccess access,TransactionRunner tx){this.runtime=runtime;this.recordings=recordings;this.access=access;this.tx=tx;}
 @GetMapping("/api/v1/recordings/{sessionId}/transcription-source") ResponseEntity<Map<String,Object>> read(@PathVariable String sessionId,HttpServletRequest request){var actor=actor(request);available(actor,recordings.meetingId(sessionId),MeetingAccess.Action.READ);return response(200,runtime.service().read(actor,sessionId));}
 @GetMapping("/api/v1/meetings/{meetingId}/recording-transcription-source") ResponseEntity<Map<String,Object>> current(@PathVariable String meetingId,HttpServletRequest request){var actor=actor(request);available(actor,meetingId,MeetingAccess.Action.READ);return response(200,runtime.service().readCurrent(actor,meetingId));}
 @PostMapping(value="/api/v1/recordings/{sessionId}/transcription-source",consumes="application/json") ResponseEntity<Map<String,Object>> prepare(@PathVariable String sessionId,HttpServletRequest request)throws IOException{var actor=actor(request);empty(request);String key=key(request);available(actor,recordings.meetingId(sessionId),MeetingAccess.Action.EDIT);return response(202,runtime.service().accept(actor,sessionId,key));}
 @PostMapping(value="/api/v1/meetings/{meetingId}/recording-transcription-source",consumes="application/json") ResponseEntity<Map<String,Object>> prepareCurrent(@PathVariable String meetingId,HttpServletRequest request)throws IOException{var actor=actor(request);empty(request);String key=key(request);available(actor,meetingId,MeetingAccess.Action.EDIT);return response(202,runtime.service().acceptCurrent(actor,meetingId,key));}
 private void available(Actor actor,String meeting,MeetingAccess.Action action){if(runtime.service()!=null)return;tx.required(()->{access.require(access.lock(actor,meeting),action);return null;});throw new IllegalStateException("Recording transcription unavailable");}
 private void empty(HttpServletRequest request)throws IOException{if(request.getContentLengthLong()>256)throw new RecordingJson.TooLarge();byte[] bytes=request.getInputStream().readNBytes(257);if(bytes.length>256)throw new RecordingJson.TooLarge();try{var body=json.readTree(bytes);if(body==null||!body.isObject()||!body.isEmpty())throw new IllegalArgumentException("Empty recording source command required");}catch(com.fasterxml.jackson.core.JacksonException invalid){throw new IllegalArgumentException("Invalid recording source command");}}
 private static String key(HttpServletRequest r){var values=Collections.list(r.getHeaders("Idempotency-Key"));if(values.size()!=1)throw new IllegalArgumentException("One stable source command key required");ama.contract.OutboxContracts.uuid(values.getFirst());return values.getFirst();}
 private static Actor actor(HttpServletRequest r){if(!(r.getAttribute(SessionSecurityFilter.SESSION) instanceof ResolvedSession s))throw new MeetingAccess.AccessDeniedException();return s.actor();}
 private static ResponseEntity<Map<String,Object>> response(int status,Map<String,Object> value){return ResponseEntity.status(status).header("Cache-Control","private, no-store").body(value);}
}
